# Find files that have sheet1 with F1 Expected Result or formulas A2+1001
hits=[]
for path in glob.glob('/tmp/**/*.xlsx', recursive=True):
    try:
        wb=openpyxl.load_workbook(path, data_only=False)
        if 'Sheet1' not in wb.sheetnames:
            continue
        ws=wb['Sheet1']
        f1=ws['F1'].value
        a3=ws['A3'].value
        if f1=='Expected Result' and isinstance(a3,str) and 'A2+1001' in a3:
            hits.append(path)
    except Exception as e:
        pass
print(len(hits))
for h in hits:
    print(h)
